#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<string> grid(n);
    for (int i = 0; i < n; i++) {
        cin >> grid[i];
    }

    // Find initial position of vehicle 'V'
    int sr = -1, sc = -1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[i][j] == 'V') {
                sr = i; sc = j;
                grid[i][j] = '0'; // treat it as empty for state
            }
        }
    }

    // encode grid state as integer (bitmask of infected cells)
    auto encode = [&](const vector<string>& g) {
        int mask = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (g[i][j] == '1') {
                    mask |= (1 << (i * m + j));
                }
            }
        }
        return mask;
    };

    int startMask = encode(grid);
    int totalCells = n * m;
    vector<vector<int>> dist(totalCells, vector<int>(1 << totalCells, -1));
    queue<pair<int,int>> q;
    int startPos = sr * m + sc;
    dist[startPos][startMask] = 0;
    q.push({startPos, startMask});

    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    while (!q.empty()) {
        auto [pos, mask] = q.front(); q.pop();
        int r = pos / m, c = pos % m;
        int d = dist[pos][mask];

        // check if all disinfected
        if (mask == 0) {
            cout << d << "\n";
            return 0;
        }

        // Try moving to adjacent uninfected cells
        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
            int npos = nr * m + nc;

            // can only move if target cell is not infected (mask bit = 0)
            if (mask & (1 << npos)) continue;

            // After moving, disinfect adjacent cells (up, down, left, right)
            int newMask = mask;
            for (int dir = 0; dir < 4; dir++) {
                int adjR = nr + dr[dir], adjC = nc + dc[dir];
                if (adjR < 0 || adjR >= n || adjC < 0 || adjC >= m) continue;
                int adjPos = adjR * m + adjC;
                if (newMask & (1 << adjPos)) {
                    newMask ^= (1 << adjPos); // disinfect
                }
            }

            if (dist[npos][newMask] == -1) {
                dist[npos][newMask] = d + 1;
                q.push({npos, newMask});
            }
        }
    }

    cout << -1 << "\n";
    return 0;
}

