#include <bits/stdc++.h>
using namespace std;

/*
This is the classic "minimum moves to move a 2-cell snake to target" problem.

State:
  (r, c, dir)
where (r, c) is the top-left / upper-left cell of the snake:
  dir = 0 -> horizontal, occupies (r,c) and (r,c+1)
  dir = 1 -> vertical,   occupies (r,c) and (r+1,c)

Start:
  (0, 0, horizontal)

Target:
  (n-1, n-2, horizontal)

Transitions:
From horizontal:
  1) Move right if grid[r][c+2] == 0
  2) Move down  if grid[r+1][c] == 0 and grid[r+1][c+1] == 0
  3) Rotate clockwise to vertical if same cells as move down are free

From vertical:
  1) Move down if grid[r+2][c] == 0
  2) Move right if grid[r][c+1] == 0 and grid[r+1][c+1] == 0
  3) Rotate counterclockwise to horizontal if same cells as move right are free

Use BFS for minimum moves.
*/

struct State {
    int r, c, d, dist;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<vector<int>> grid(n, vector<int>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) cin >> grid[i][j];
    }

    // visited[r][c][d]
    vector<vector<array<bool, 2>>> vis(n, vector<array<bool, 2>>(n, {false, false}));
    queue<State> q;

    // Start must be valid
    if (n < 2 || grid[0][0] || grid[0][1]) {
        cout << -1 << '\n';
        return 0;
    }

    q.push({0, 0, 0, 0});
    vis[0][0][0] = true;

    while (!q.empty()) {
        auto [r, c, d, dist] = q.front();
        q.pop();

        if (r == n - 1 && c == n - 2 && d == 0) {
            cout << dist << '\n';
            return 0;
        }

        if (d == 0) { // horizontal
            // Move right
            if (c + 2 < n && grid[r][c + 2] == 0) {
                if (!vis[r][c + 1][0]) {
                    vis[r][c + 1][0] = true;
                    q.push({r, c + 1, 0, dist + 1});
                }
            }
            // Move down / rotate clockwise
            if (r + 1 < n && grid[r + 1][c] == 0 && grid[r + 1][c + 1] == 0) {
                // Move down
                if (!vis[r + 1][c][0]) {
                    vis[r + 1][c][0] = true;
                    q.push({r + 1, c, 0, dist + 1});
                }
                // Rotate to vertical
                if (!vis[r][c][1]) {
                    vis[r][c][1] = true;
                    q.push({r, c, 1, dist + 1});
                }
            }
        } else { // vertical
            // Move down
            if (r + 2 < n && grid[r + 2][c] == 0) {
                if (!vis[r + 1][c][1]) {
                    vis[r + 1][c][1] = true;
                    q.push({r + 1, c, 1, dist + 1});
                }
            }
            // Move right / rotate counterclockwise
            if (c + 1 < n && grid[r][c + 1] == 0 && grid[r + 1][c + 1] == 0) {
                // Move right
                if (!vis[r][c + 1][1]) {
                    vis[r][c + 1][1] = true;
                    q.push({r, c + 1, 1, dist + 1});
                }
                // Rotate to horizontal
                if (!vis[r][c][0]) {
                    vis[r][c][0] = true;
                    q.push({r, c, 0, dist + 1});
                }
            }
        }
    }

    cout << -1 << '\n';
    return 0;
}

