#define MAXN 4
#define MAXMASK (1 << 16)

typedef struct {
    int x, y;
    int mask;
    int dist;
} State;

int n, m;
int dx[] = {0, 0, 1, -1};
int dy[] = {1, -1, 0, 0};
int visited[MAXN][MAXN][MAXMASK];

int bfs(int start_x, int start_y, int start_mask) {
    memset(visited, -1, sizeof(visited));
    State q[MAXN * MAXN * MAXMASK];
    int front = 0, rear = 0;

    q[rear++] = (State){start_x, start_y, start_mask, 0};
    visited[start_x][start_y][start_mask] = 0;

    while (front < rear) {
        State cur = q[front++];
        int x = cur.x, y = cur.y, mask = cur.mask, dist = cur.dist;

        if (mask == 0) return dist;

        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx < 0 || ny < 0 || nx >= n || ny >= m) continue;

            int bit = nx * m + ny;
            if (mask & (1 << bit)) continue; // cannot move to infected

            int new_mask = mask;
            // disinfect current cell after moving
            int cur_bit = x * m + y;
            new_mask &= ~(1 << cur_bit);

            // infect adjacent cells (including current vehicle cell)
            for (int dd = 0; dd < 4; dd++) {
                int ax = x + dx[dd];
                int ay = y + dy[dd];
                if (ax >= 0 && ay >= 0 && ax < n && ay < m) {
                    int ab = ax * m + ay;
                    new_mask |= (1 << ab);
                }
            }
            // also infect the cell we just left (if not already)
            // Actually the current cell (x,y) is already handled by the loop above (dd loop includes it? No, we add only adjacent)
            // But the problem says "adjacent areas" meaning up/down/left/right. 
            // The vehicle's position influences adjacent cells. 
            // So when vehicle leaves a cell, that cell gets infected if adjacent to vehicle? No, only cells adjacent to vehicle get infected.
            // We already added infection for adjacent cells in the loop above.

            if (visited[nx][ny][new_mask] == -1) {
                visited[nx][ny][new_mask] = dist + 1;
                q[rear++] = (State){nx, ny, new_mask, dist + 1};
            }
        }
    }
    return -1;
}

int main() {
    char line[10];
    int start_x = -1, start_y = -1, mask = 0;

    n = 0;
    while (fgets(line, sizeof(line), stdin)) {
        if (line[0] == '\n' || line[0] == '\0') break;
        m = strlen(line);
        if (line[m-1] == '\n') line[--m] = '\0';
        for (int j = 0; j < m; j++) {
            if (line[j] == 'S') {
                start_x = n;
                start_y = j;
            } else if (line[j] == 'I') {
                mask |= (1 << (n * m + j));
            }
        }
        n++;
    }

    if (start_x == -1) {
        printf("-1\n");
        return 0;
    }

    printf("%d\n", bfs(start_x, start_y, mask));
    return 0;
}

