#define MAXN 20
#define MAXCELLS 20

int n;
char grid[MAXN][MAXN+2];
int dr[] = {0,0,1,-1};
int dc[] = {1,-1,0,0};

// BFS state: (r, c, mask of infected cells)
// infected cells indexed 0..k-1
int inf_r[MAXCELLS], inf_c[MAXCELLS], inf_cnt;
int start_r, start_c;

typedef struct { int r, c, mask; } State;

#define HASH_SIZE (1<<22)
int visited[MAXN][MAXN][1<<16]; // too large potentially

int main(){
    scanf("%d", &n);
    inf_cnt = 0;
    for(int i=0;i<n;i++){
        scanf("%s", grid[i]);
        for(int j=0;j<n;j++){
            if(grid[i][j]=='S'||grid[i][j]=='@'||grid[i][j]=='s'){
                start_r=i; start_c=j; grid[i][j]='0';
            } else if(grid[i][j]=='1'){
                inf_r[inf_cnt]=i; inf_c[inf_cnt]=j; inf_cnt++;
            }
        }
    }
    if(inf_cnt==0){printf("0\n");return 0;}
    if(inf_cnt>16){printf("-1\n");return 0;}

    int full = (1<<inf_cnt)-1;
    // BFS
    static int vis[MAXN][MAXN][1<<16];
    memset(vis,-1,sizeof(vis));

    // compute initial mask (vehicle disinfects adjacent on start)
    int init_mask = full;
    for(int k=0;k<inf_cnt;k++){
        for(int d=0;d<4;d++){
            if(inf_r[k]+dr[d]==start_r && inf_c[k]+dc[d]==start_c){
                init_mask &= ~(1<<k);
            }
        }
    }

    if(init_mask==0){printf("0\n");return 0;}

    State *q = malloc(sizeof(State)*n*n*(1<<inf_cnt)*4);
    int head=0,tail=0;
    q[tail++]=(State){start_r,start_c,init_mask};
    vis[start_r][start_c][init_mask]=0;

    while(head<tail){
        State cur=q[head++];
        int steps=vis[cur.r][cur.c][cur.mask];
        for(int d=0;d<4;d++){
            int nr=cur.r+dr[d], nc=cur.c+dc[d];
            if(nr<0||nr>=n||nc<0||nc>=n) continue;
            // check if nr,nc is infected
            int is_inf=0;
            for(int k=0;k<inf_cnt;k++) if((cur.mask>>k&1)&&inf_r[k]==nr&&inf_c[k]==nc){is_inf=1;break;}
            if(is_inf) continue;
            int nm=cur.mask;
            for(int k=0;k<inf_cnt;k++) if(nm>>k&1){
                for(int d2=0;d2<4;d2++) if(inf_r[k]+dr[d2]==nr&&inf_c[k]+dc[d2]==nc) nm&=~(1<<k);
            }
            if(nm==0){printf("%d\n",steps+1);return 0;}
            if(vis[nr][nc][nm]==-1){vis[nr][nc][nm]=steps+1;q[tail++]=(State){nr,nc,nm};}
        }
    }
    printf("-1\n");
    free(q);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
Assumed input format:
n m
sx sy
grid of n lines, each with m characters:
  '.' = uninfected / free cell
  '#' = blocked cell
  '*' = infected cell

Rules used:
- Vehicle starts at (sx, sy), 0-based or 1-based is not explicitly stated in problem text.
  We accept 1-based if coordinates are within 1..n / 1..m, and convert to 0-based.
- Vehicle may move in 4 directions to non-blocked, currently uninfected cells only.
- Infection state toggles for the 4-neighbors of the vehicle's current position whenever it moves onto a cell
  (including the initial position as the starting state influence).
- Goal: all non-blocked cells become uninfected.
- Return minimum number of moves, or -1 if impossible.

Because the original statement is incomplete/ambiguous, this solution implements the standard BFS over:
(position, infection bitmask)
which is the natural interpretation of "position influences adjacent areas" and
"minimum moves required to disinfect completely".

Constraints are not provided; this approach is suitable for small grids.
Only non-blocked cells are included in the bitmask state.
*/

typedef struct {
    int pos;
    unsigned long long mask;
    int dist;
} State;

typedef struct {
    State *a;
    int head, tail, cap;
} Queue;

static void qinit(Queue *q, int cap) {
    q->a = (State *)malloc(sizeof(State) * cap);
    q->head = q->tail = 0;
    q->cap = cap;
}

static int qempty(Queue *q) {
    return q->head == q->tail;
}

static void qpush(Queue *q, State s) {
    q->a[q->tail++] = s;
}

static State qpop(Queue *q) {
    return q->a[q->head++];
}

typedef struct {
    unsigned long long keyMask;
    int keyPos;
    char used;
} VisEntry;

static unsigned long long mix64(unsigned long long x) {
    x ^= x >> 30;
    x *= 0xbf58476d1ce4e5b9ULL;
    x ^= x >> 27;
    x *= 0x94d049bb133111ebULL;
    x ^= x >> 31;
    return x;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int sx, sy;
    if (scanf("%d %d", &sx, &sy) != 2) return 0;

    char **grid = (char **)malloc(sizeof(char *) * n);
    for (int i = 0; i < n; i++) {
        grid[i] = (char *)malloc(m + 5);
        scanf("%s", grid[i]);
    }

    if (sx >= 1 && sx <= n && sy >= 1 && sy <= m) {
        sx--; sy--;
    }

    if (sx < 0 || sx >= n || sy < 0 || sy >= m || grid[sx][sy] == '#') {
        printf("-1\n");
        return 0;
    }

    int totalCells = 0;
    int *id = (int *)malloc(sizeof(int) * n * m);
    for (int i = 0; i < n * m; i++) id[i] = -1;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[i][j] != '#') {
                id[i * m + j] = totalCells++;
            }
        }
    }

    if (totalCells > 63) {
        /* This implementation uses 64-bit masks. */
        printf("-1\n");
        return 0;
    }

    unsigned long long initMask = 0ULL;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[i][j] == '*') {
                int k = id[i * m + j];
                if (k >= 0) initMask |= (1ULL << k);
            }
        }
    }

    int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};

    /* Precompute toggle mask caused by standing on each free cell:
       toggles infection state of its 4-neighbors. */
    unsigned long long *toggle = (unsigned long long *)calloc(totalCells, sizeof(unsigned long long));
    int *cellx = (int *)malloc(sizeof(int) * totalCells);
    int *celly = (int *)malloc(sizeof(int) * totalCells);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            int p = id[i * m + j];
            if (p < 0) continue;
            cellx[p] = i;
            celly[p] = j;
            unsigned long long t = 0ULL;
            for (int d = 0; d < 4; d++) {
                int ni = i + dirs[d][0], nj = j + dirs[d][1];
                if (ni >= 0 && ni < n && nj >= 0 && nj < m && grid[ni][nj] != '#') {
                    int q = id[ni * m + nj];
                    t ^= (1ULL << q);
                }
            }
            toggle[p] = t;
        }
    }

    int startPos = id[sx * m + sy];
    unsigned long long startMask = initMask ^ toggle[startPos];

    if (((startMask >> startPos) & 1ULL) == 1ULL) {
        /* Vehicle can only be on uninfected cell; initial influence made start infected. */
        printf("-1\n");
        return 0;
    }

    if (startMask == 0ULL) {
        printf("0\n");
        return 0;
    }

    /* BFS */
    int maxStatesGuess = 1 << 20;
    Queue q;
    qinit(&q, maxStatesGuess);

    int visCap = 1 << 22;
    VisEntry *vis = (VisEntry *)calloc(visCap, sizeof(VisEntry));

    #define VIS_HASH(mask,pos) ((int)(mix64((mask) ^ ((unsigned long long)(pos) * 11995408973635179863ULL)) & (visCap - 1)))

    auto int vis_insert(unsigned long long mask, int pos) {
        int h = VIS_HASH(mask, pos);
        while (vis[h].used) {
            if (vis[h].keyMask == mask && vis[h].keyPos == pos) return 0;
            h = (h + 1) & (visCap - 1);
        }
        vis[h].used = 1;
        vis[h].keyMask = mask;
        vis[h].keyPos = pos;
        return 1;
    }

    vis_insert(startMask, startPos);
    qpush(&q, (State){startPos, startMask, 0});

    while (!qempty(&q)) {
        State cur = qpop(&q);
        int x = cellx[cur.pos], y = celly[cur.pos];

        for (int d = 0; d < 4; d++) {
            int nx = x + dirs[d][0], ny = y + dirs[d][1];
            if (nx < 0 || nx >= n || ny < 0 || ny >= m || grid[nx][ny] == '#') continue;
            int np = id[nx * m + ny];

            /* Can only move to currently uninfected cell */
            if (((cur.mask >> np) & 1ULL) != 0ULL) continue;

            unsigned long long nmask = cur.mask ^ toggle[np];

            /* Vehicle must remain on uninfected cell after move effect */
            if (((nmask >> np) & 1ULL) != 0ULL) continue;

            if (nmask == 0ULL) {
                printf("%d\n", cur.dist + 1);
                return 0;
            }

            if (vis_insert(nmask, np)) {
                if (q.tail >= q.cap) {
                    q.cap <<= 1;
                    q.a = (State *)realloc(q.a, sizeof(State) * q.cap);
                }
                qpush(&q, (State){np, nmask, cur.dist + 1});
            }
        }
    }

    printf("-1\n");
    return 0;
}

import java.util.*;

public class DisinfectGrid {
    static int[] dr = {-1, 1, 0, 0};
    static int[] dc = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int R = sc.nextInt();
        int C = sc.nextInt();
        sc.nextLine();

        int startMask = 0;
        int startR = -1, startC = -1;

        for (int r = 0; r < R; r++) {
            String line = sc.nextLine().trim();
            for (int c = 0; c < C; c++) {
                char ch = line.charAt(c);
                if (ch == 'I') {
                    startMask |= (1 << (r * C + c));
                } else if (ch == 'V') {
                    startR = r;
                    startC = c;
                }
            }
        }

        int totalCells = R * C;
        int startPos = startR * C + startC;

        // BFS
        boolean[][][] visited = new boolean[R][C][1 << totalCells];
        Queue<int[]> queue = new LinkedList<>();
        // state: [r, c, mask, steps]
        queue.add(new int[]{startR, startC, startMask, 0});
        visited[startR][startC][startMask] = true;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0], c = cur[1], mask = cur[2], steps = cur[3];

            if (mask == 0) {
                System.out.println(steps);
                return;
            }

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
                int nIdx = nr * C + nc;

                // can only move to uninfected cell
                if ((mask & (1 << nIdx)) != 0) continue;

                int newMask = mask;
                // toggle neighbors (including the new position? problem says adjacent areas, meaning orthogonal neighbors of vehicle)
                // Actually the vehicle's position influences adjacent areas, so when moving to (nr,nc), toggle its neighbors
                for (int dd = 0; dd < 4; dd++) {
                    int nnr = nr + dr[dd];
                    int nnc = nc + dc[dd];
                    if (nnr < 0 || nnr >= R || nnc < 0 || nnc >= C) continue;
                    int nnIdx = nnr * C + nnc;
                    newMask ^= (1 << nnIdx);
                }

                if (!visited[nr][nc][newMask]) {
                    visited[nr][nc][newMask] = true;
                    queue.add(new int[]{nr, nc, newMask, steps + 1});
                }
            }
        }

        System.out.println(-1);
    }
}

