        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[][] grid = new int[n][n];
        int startR = -1, startC = -1;
        int initMask = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                grid[i][j] = sc.nextInt();
                if (grid[i][j] == 1) initMask |= (1 << (i * n + j));
                else if (startR == -1) { startR = i; startC = j; }
            }
        }

        if (initMask == 0) { System.out.println(0); return; }

        int[] dx = {0,0,1,-1};
        int[] dy = {1,-1,0,0};

        // State: (r, c, mask)
        Map<Long, Integer> dist = new HashMap<>();
        Queue<long[]> queue = new LinkedList<>();

        // Disinfect adjacent to start
        int mask = initMask;
        for (int d = 0; d < 4; d++) {
            int nr = startR + dx[d], nc = startC + dy[d];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n)
                mask &= ~(1 << (nr * n + nc));
        }

        long startState = ((long)(startR * n + startC) << 32) | mask;
        dist.put(startState, 0);
        queue.add(new long[]{startR, startC, mask});

        while (!queue.isEmpty()) {
            long[] cur = queue.poll();
            int r = (int)cur[0], c = (int)cur[1], m = (int)cur[2];
            int steps = dist.get(((long)((r*n+c)) << 32) | m);

            if (m == 0) { System.out.println(steps); return; }

            for (int d = 0; d < 4; d++) {
                int nr = r + dx[d], nc = c + dy[d];
                if (nr < 0 || nr >= n || nc < 0 || nc >= n) continue;
                if ((m & (1 << (nr * n + nc))) != 0) continue; // infected cell

                int nm = m;
                for (int d2 = 0; d2 < 4; d2++) {
                    int nnr = nr + dx[d2], nnc = nc + dy[d2];
                    if (nnr >= 0 && nnr < n && nnc >= 0 && nnc < n)
                        nm &= ~(1 << (nnr * n + nnc));
                }

                long ns = ((long)(nr * n + nc) << 32) | nm;
                if (!dist.containsKey(ns)) {
                    dist.put(ns, steps + 1);
                    queue.add(new long[]{nr, nc, nm});
                }
            }
        }
        System.out.println(-1);
    }
}

import java.io.*;
import java.util.*;

/*
We model the problem as a shortest-path search on states.

State:
- vehicle position (r, c), only on currently uninfected cell
- infection mask of the whole grid

At each move, the vehicle moves to one of 4-neighbor cells that is currently uninfected.
After moving, the infection state of adjacent cells changes according to the vehicle's
position. Since the statement is abbreviated, we use the standard interpretation for
this type of problem: all 4-neighbors of the vehicle are disinfected (set to 0).

Goal:
- all cells disinfected (mask == 0)

Input format assumed:
n m
grid of n lines consisting of:
'.' = uninfected cell
'*' = infected cell
'S' = vehicle start position (also uninfected)

Output:
minimum number of moves, or -1 if impossible.

This solution is intended for small grids (typical for state-compression BFS).
*/

public class Main {
    static class State {
        int pos;
        int mask;
        int dist;
        State(int pos, int mask, int dist) {
            this.pos = pos;
            this.mask = mask;
            this.dist = dist;
        }
    }

    static final int[] DR = {-1, 1, 0, 0};
    static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first;
        while ((first = br.readLine()) != null && first.trim().isEmpty()) {}
        if (first == null) return;

        StringTokenizer st = new StringTokenizer(first);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        char[][] g = new char[n][m];
        int start = -1;
        int initMask = 0;

        for (int i = 0; i < n; i++) {
            String s = br.readLine();
            while (s != null && s.length() < m) {
                String extra = br.readLine();
                if (extra == null) break;
                s += extra;
            }
            for (int j = 0; j < m; j++) {
                char ch = s.charAt(j);
                g[i][j] = ch;
                int id = i * m + j;
                if (ch == 'S') start = id;
                if (ch == '*') initMask |= (1 << id);
            }
        }

        if (start == -1) {
            System.out.println(-1);
            return;
        }

        // Apply effect at initial position as well: disinfect adjacent cells.
        initMask = applyDisinfect(start, initMask, n, m);

        if (initMask == 0) {
            System.out.println(0);
            return;
        }

        int totalCells = n * m;
        int maxMask = 1 << totalCells;

        boolean[][] vis = new boolean[totalCells][];
        for (int i = 0; i < totalCells; i++) vis[i] = new boolean[maxMask];

        ArrayDeque<State> q = new ArrayDeque<>();
        vis[start][initMask] = true;
        q.offer(new State(start, initMask, 0));

        while (!q.isEmpty()) {
            State cur = q.poll();
            int r = cur.pos / m;
            int c = cur.pos % m;

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;

                int np = nr * m + nc;

                // Vehicle can only move to currently uninfected areas.
                if (((cur.mask >> np) & 1) == 1) continue;

                int nmask = applyDisinfect(np, cur.mask, n, m);

                if (nmask == 0) {
                    System.out.println(cur.dist + 1);
                    return;
                }

                if (!vis[np][nmask]) {
                    vis[np][nmask] = true;
                    q.offer(new State(np, nmask, cur.dist + 1));
                }
            }
        }

        System.out.println(-1);
    }

    static int applyDisinfect(int pos, int mask, int n, int m) {
        int r = pos / m;
        int c = pos % m;
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
            int id = nr * m + nc;
            mask &= ~(1 << id);
        }
        return mask;
    }
}

from collections import deque

def solve():
    import sys
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    n = int(next(it))
    m = int(next(it))
    grid = []
    start = None
    for i in range(n):
        row = []
        for j in range(m):
            cell = next(it)
            row.append(cell)
            if cell == 'V':
                start = (i, j)
        grid.append(row)

    # encode infection as bitmask: 1 = infected
    initial_infected = 0
    idx = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'I':
                initial_infected |= (1 << idx)
            idx += 1

    total_cells = n * m
    # directions for infection spread and movement
    dirs = [(1,0), (-1,0), (0,1), (0,-1)]

    # BFS: state = (x, y, infected_mask)
    start_state = (start[0], start[1], initial_infected)
    dist = {}
    dist[start_state] = 0
    q = deque([start_state])

    while q:
        x, y, mask = q.popleft()
        # if no infection left, we are done
        if mask == 0:
            print(dist[(x, y, mask)])
            return

        # infection spread for next step:
        # first compute what gets infected from current infected cells
        new_infected = mask
        for i in range(n):
            for j in range(m):
                if mask & (1 << (i * m + j)):
                    for dx, dy in dirs:
                        ni, nj = i + dx, j + dy
                        if 0 <= ni < n and 0 <= nj < m:
                            new_infected |= (1 << (ni * m + nj))

        # Now the vehicle moves
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                # can only move into uninfected cells (before infection spread this turn)
                if (mask & (1 << (nx * m + ny))) == 0:
                    # disinfect surrounding after movement
                    after_vehicle = new_infected
                    # vehicle disinfects itself and neighbors
                    after_vehicle &= ~(1 << (nx * m + ny))
                    for ddx, ddy in dirs:
                        nnx, nny = nx + ddx, ny + ddy
                        if 0 <= nnx < n and 0 <= nny < m:
                            after_vehicle &= ~(1 << (nnx * m + nny))
                    new_state = (nx, ny, after_vehicle)
                    if new_state not in dist:
                        dist[new_state] = dist[(x, y, mask)] + 1
                        q.append(new_state)

        # Also option: stay in place (but must be uninfected before spread)
        if (mask & (1 << (x * m + y))) == 0:
            after_vehicle = new_infected
            after_vehicle &= ~(1 << (x * m + y))
            for ddx, ddy in dirs:
                nnx, nny = x + ddx, y + ddy
                if 0 <= nnx < n and 0 <= nny < m:
                    after_vehicle &= ~(1 << (nnx * m + nny))
            new_state = (x, y, after_vehicle)
            if new_state not in dist:
                dist[new_state] = dist[(x, y, mask)] + 1
                q.append(new_state)

    print(-1)

if __name__ == "__main__":
    solve()

